describe('Async PDF Generation', () => {
    beforeEach(() => {
        cy.visit('/pdf-generation-page');
    });

    it('should download the PDF when generation is complete', () => {
        cy.intercept('GET', '/api/pdf/generate', { statusCode: 200 }).as('pdfGeneration');
        cy.get('button#generate-pdf').click();
        cy.wait('@pdfGeneration');
        cy.get('a#download-pdf').should('be.visible').click();
        cy.readFile('cypress/downloads/generated.pdf').should('exist');
    });

    it('should show an error message if PDF generation fails', () => {
        cy.intercept('GET', '/api/pdf/generate', { statusCode: 500 }).as('pdfGenerationError');
        cy.get('button#generate-pdf').click();
        cy.wait('@pdfGenerationError');
        cy.get('.error-message').should('be.visible').and('contain', 'PDF generation failed. Please try again.');
    });
});
